2	
3	/// [REQ-ENG-1/4] Engine facade: host-agnostic render entry + the load-bearing
4	/// atomic program swap with generation-gated deferred reclamation (spec 01 §1.4).
5	///
6	/// P0 limitations (tracked, deliberate):
7	/// - Commands apply at block start; sample-offset scheduling within the block
8	///   (AT-ENG-5 second half) lands with the MIDI integration.
9	/// - FTZ/denormal flushing (§1.2 rule 4) not yet enabled — needs per-arch FPCR
10	///   code verified on hardware.
11	public final class Engine {
12	    public let commandRing: CommandRing
13	    private let active = ManagedAtomic<UnsafeMutableRawPointer?>(nil)
14	    private let rtGeneration = ManagedAtomic<UInt64>(0)
15	    private var retired: [(gen: UInt64, ref: Unmanaged<Program>)] = []   // UI thread only
16	    private var nextGeneration: UInt64 = 0                               // UI thread only
17	
18	    public init(commandRingCapacity: Int = 4096) {
19	        commandRing = CommandRing(capacity: commandRingCapacity)
20	    }
21	    deinit {
22	        if let raw = active.load(ordering: .acquiring) {
23	            Unmanaged<Program>.fromOpaque(raw).release()
24	        }
25	        for r in retired { r.ref.release() }
26	    }
27	
28	    /// UI thread. Swaps the active program; never blocks the RT thread.
29	    public func install(program: Program) {
30	        nextGeneration += 1
31	        program.generation = nextGeneration
32	        let newRaw = Unmanaged.passRetained(program).toOpaque()
33	        let oldRaw = active.exchange(newRaw, ordering: .acquiringAndReleasing)
34	        if let oldRaw = oldRaw {
35	            let old = Unmanaged<Program>.fromOpaque(oldRaw)
36	            retired.append((gen: old.takeUnretainedValue().generation, ref: old))
37	        }
38	        reclaim()
39	    }
40	
41	    /// UI thread, poll at display rate. Frees retired programs the RT thread
42	    /// has provably moved past (rtGeneration >= a program installed AFTER it).
43	    public func reclaim() {
44	        let seen = rtGeneration.load(ordering: .acquiring)
45	        // A retired program (gen g) is safe to free once the RT thread has
46	        // rendered a block with a NEWER program (seen > g).
47	        retired.removeAll { entry in
48	            if seen > entry.gen { entry.ref.release(); return true }
49	            return false
50	        }
51	    }
52	
53	    /// True when nothing is awaiting reclamation (test hook).
54	    public var retiredCount: Int { retired.count }
55	
56	    @discardableResult
57	    public func send(_ command: ParameterCommand) -> Bool { commandRing.push(command) }
58	
59	    /// RT thread. Renders into non-interleaved L/R buffers.
60	    public func render(left: UnsafeMutablePointer<Float>, right: UnsafeMutablePointer<Float>,
61	                       frameCount: Int, context: RenderContext) {
62	        guard let raw = active.load(ordering: .acquiring) else {
63	            for i in 0..<frameCount { left[i] = 0; right[i] = 0 }
64	            return
65	        }
66	        let program = Unmanaged<Program>.fromOpaque(raw).takeUnretainedValue()
67	        let frames = min(frameCount, program.maxBlockSize)
68	
69	        // Drain command ring at block start (P0: applied at frame 0).
70	        while let cmd = commandRing.pop() { program.apply(cmd) }
71	
72	        program.execute(frames: frames, ctx: context)
73	
74	        if let l = program.masterL, let r = program.masterR {
75	            for i in 0..<frames { left[i] = l[i]; right[i] = r[i] }
76	        } else {
77	            for i in 0..<frames { left[i] = 0; right[i] = 0 }
78	        }
79	        rtGeneration.store(program.generation, ordering: .releasing)
80	    }
81	}
